Q: Download a single folder or directory from a GitHub repository A: <p>A more complete solution as none of the other answers actually describe how to do it</p>
<p>Download a zipped directory right here in the browser by running this code snippet.</p>
<p>The path can be empty (therefore it will download all files in the repository).</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-css lang-css prettyprint-override"><code>body      {display: flex; flex-direction: column; font-family: arial; margin: 0}
#title    {margin: 0; font-size: 12px; display: flex}
section   {display: grid; grid-template-columns: auto 1fr; gap: 3px; align-items: center; margin: 3px}
input     {font-size: 16px; padding: 2px 5px}
button    {cursor: pointer; width: 200px; font-size: 16px; padding: 2px}
#auto     {margin: 0 30px}
#download {display: flex}
#progress {flex: 1; margin: 0 3px 0 10px; border: 1px solid blue; padding: 1px; position: relative}
#bar      {background: lightblue; width: 0; position: absolute; inset: 2px 2px 2px 2px}
#output   {display: none; font-size: 16px; margin: 0}</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;div id=title&gt;download a directory from a github repository&lt;span style=flex:1&gt;&lt;/span&gt;
  &lt;a href='https://github.com/javascript-2020/stackoverflow' style=text-decoration:none&gt;try : javascript-2020 : stackoverflow : main&lt;/a&gt;
  &lt;a id=auto href='#' onclick='auto(); return false;'&gt;auto&lt;/a&gt;
&lt;/div&gt;
&lt;section&gt;
      &lt;div&gt;owner&lt;/div&gt;&lt;input class=owner&gt;
      &lt;div&gt;repo&lt;/div&gt;&lt;input class=repo&gt;
      &lt;div&gt;branch&lt;/div&gt;&lt;input class=branch&gt;
      &lt;div&gt;path&lt;/div&gt;&lt;input class=path&gt;
&lt;/section&gt;
&lt;div id=download&gt;
      &lt;button onclick=download()&gt;download&lt;/button&gt;
      &lt;div id=progress style='display:none'&gt;&lt;div id=bar&gt;&lt;/div&gt;&lt;/div&gt;
&lt;/div&gt;
&lt;pre id=output&gt;&lt;/pre&gt;

&lt;script type=module&gt;

  import jszip from 'https://cdn.jsdelivr.net/npm/jszip/+esm';
  var $ = sel =&gt; document.querySelector(sel);

  window.auto = function() {
        $('.owner').value     = 'javascript-2020';
        $('.repo').value      = 'stackoverflow';
        $('.branch').value    = 'main';
        download();
        return false;
  } // auto

  window.download = async function() {

        $('#progress').style.display = '';

        var owner   = $('.owner').value;
        var repo    = $('.repo').value;
        var branch  = $('.branch').value;
        var path    = $('.path').value;

        if(path[0] == '/')
            path = path.slice(1);
        if(path &amp;&amp; path.slice(-1) != '/')
            path += '/';

        var url     = `https://api.github.com/repos/${owner}/${repo}/git/trees/${branch}?recursive=true`;
        var json    = await fetch(url).then(res=&gt;res.json());
        var file    = `${path.split('/').filter(Boolean).at(-1)||repo}.zip`;
        var zip     = new jszip();

        var total   = 2;
        var c       = 1;

        await Promise.all(json.tree.map(async item =&gt; {

            if(!item.path.startsWith(path))
                return;

            total++;
            $('#bar').style.width = `calc(${100*c/total}% - 4px)`;

            var fn = item.path.slice(path.length);
            if(item.type == 'tree') {
                zip.folder(fn);
            }
            else {
                var url     = `https://raw.githubusercontent.com/${owner}/${repo}/${branch}/${item.path}`;
                var blob    = await fetch(url).then(res =&gt; res.blob());
                zip.file(fn, blob);
            }

            c++;
            $('#bar').style.width = `calc(${100*c/total}% - 4px)`;
        }));

        var blob                = await zip.generateAsync({type:'blob'});

        $('#bar').style.width   = 'calc(100% - 4px)';
        output.style.display    = 'block';
        var url                 = window.URL.createObjectURL(blob);
        var a                   = document.createElement('a');
        a.href                  = url;
        a.download              = file;
        a.textContent           = file + ' (right-click - save link as)';
        output.append(a, '\n');
  } // Download
&lt;/script&gt;</code></pre>
</div>
</div>
</p>
<p>A link to a GitHub webpage for a more complete example (work in progress)</p>
<p><a href="https://javascript-2020.github.io/utils/github/download-a-directory-from-a-github-repository/download-a-directory-from-a-github-repository.html" rel="nofollow noreferrer">javascript-2020.github.io: Download a directory from a GitHub repository</a></p>
<br>
<hr />
<hr />
<p>As per the documentation <a href="https://docs.github.com/en/rest/git/trees?apiVersion=2022-11-28#get-a-tree" rel="nofollow noreferrer">REST API endpoints for Git trees: Get a tree</a></p>
<p>A complete list of files for a repository can be downloaded in json format by adding <code>?recursive=true</code> to the endpoint:</p>
<pre><code>https://api.github.com/repos/${owner}/${repo}/git/trees/${branch}?recursive=true
</code></pre>
<p>Each file can be downloaded individually from <a href="https://stackoverflow.com/questions/39065921/what-do-raw-githubusercontent-com-urls-represent">raw.githubusercontent.com</a>:</p>
<pre><code>https://raw.githubusercontent.com/${owner}/${repo}/${branch}/${path}
</code></pre>
<p>And the whole process only requires 1 github api request which helps with the github api rate restrictions, 60 p/hr anonymous, 5000 p/hr authorised, there is however a delay between updating a repo and those changes being reflected at raw.githubusercontent.com, this can be 5-10 minutes.</p>
<p>Individual files can also be downloaded from ( changes reflected immediately )</p>
<pre><code>https://api.github.com/repos/${owner}/${repo}/contents/${path}
</code></pre>
<p>To use authorized requests with the github api, a http header needs to be added to the request</p>
<pre><code>authorization : bearer ${token}
</code></pre>
<p>A GitHub api token can be generated at <a href="https://github.com/settings/personal-access-tokens" rel="nofollow noreferrer">github.com: Fine-grained personal access tokens</a>, you'll need to add <code>permissions / repository permissions / contents</code> permission to the token.</p>
<p>Given a successful request the api url will return a json object with the file data base64 encoded in the content field, such as:</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>    (async () =&gt; {

          var owner     = 'javascript-2020';
          var repo      = 'tmp';
          var branch    = 'main';
          var path      = 'myfile.js';

          var token     = '';
          var headers   = {};
          if(token) {
              headers   = {authorization: `bearer ${token}`};
          }

          var url       = `https://api.github.com/repos/${owner}/${repo}/contents/${path}`;
          var json      = await fetch(url, {headers}).then(res =&gt; res.json());
          console.log(JSON.stringify(json, null, 4), '\n');

          var txt       = window.atob(json.content);
          console.log(txt);
    })();</code></pre>
</div>
</div>
</p>
<p>This structure can then be coupled with <a href="https://www.npmjs.com/package/jszip" rel="nofollow noreferrer">npm : jszip</a> to create a zip file containing the files in the folder</p>
<pre class="lang-html prettyprint-override"><code>&lt;script type=module&gt;

    import jszip from 'https://cdn.jsdelivr.net/npm/jszip/+esm';

    var owner   = 'javascript-2020';
    var repo    = 'stackoverflow';
    var branch  = 'main';
    var path    = '';

    if(path[0] == '/')
        path    = path.slice(1);
    if(path &amp;&amp; path.at(-1) != '/')
        path  += '/';

    var file    = `${path.split('/').filter(Boolean).at(-1)||repo}.zip`;
    var zip     = new jszip();
    var url     = `https://api.github.com/repos/${owner}/${repo}/git/trees/${branch}?recursive=true`;
    var json    = await fetch(url).then(res =&gt; res.json());

    await Promise.all(json.tree.map(async item =&gt; {

        if(!item.path.startsWith(path))
            return;

        var fn    = item.path.slice(path.length);
        if(item.type == 'tree') {
            zip.folder(fn);
        }
        else{
            var url     = `https://raw.githubusercontent.com/${owner}/${repo}/${branch}/${item.path}`;
            var blob    = await fetch(url).then(res =&gt; res.blob());
            zip.file(fn, blob);
        }
    }));

    var blob      = await zip.generateAsync({type:'blob'});
    var url       = window.URL.createObjectURL(blob);
    var a         = document.createElement('a');
    a.href        = url;
    a.download    = file;
    a.click();
&lt;/script&gt;
</code></pre>
<p>For those wishing to do all this in nodejs, the following will write directly to disk</p>
<pre class="lang-html prettyprint-override"><code>// download-repo-dir.node.mjs

import fs from 'fs';

var owner   = 'javascript-2020';
var repo    = 'stackoverflow';
var branch  = 'main';
var path    = '';

if(path[0]=='/')
    path    = path.slice(1);
if(path &amp;&amp; path.slice(-1) != '/')
    path  += '/';

var file    = `${path.split('/').filter(Boolean).at(-1)||repo}/`;
fs.mkdirSync(file);
var url     = `https://api.github.com/repos/${owner}/${repo}/git/trees/${branch}?recursive=true`;
var json    = await fetch(url).then(res =&gt; res.json());

json.tree.forEach(async item =&gt; {

    if(!item.path.startsWith(path))
        return;

    var fn    = item.path.slice(path.length);
    if(item.type == 'tree') {
        fs.mkdirSync(file + fn);
    }
    else {
        var fh        = fs.createWriteStream(file + fn);
        var stream    = new WritableStream({write:data =&gt; fh.write(data)});
        var url       = `https://raw.githubusercontent.com/${owner}/${repo}/${branch}/${item.path}`;
        fetch(url).then(res =&gt; res.body.pipeTo(stream));
    }
});
</code></pre>
<br>
<hr />
<hr />
<br>
<p>To get jszip working in nodejs this seems to work</p>
<pre class="lang-javascript prettyprint-override"><code>var sandbox   = {};
sandbox.cjs   = txt =&gt; Promise.resolve(eval(`(() =&gt; {var exports = {}, module = {}; ${txt}; return module.exports})()`));
var url       = 'https://raw.githubusercontent.com/stuk/jszip/main/dist/jszip.min.js';
var JSZip     = await fetch(url).then(res =&gt; res.text().then(sandbox.cjs));
console.log(JSZip);
</code></pre>
<p>There is also the <code>node --experimental-network-imports</code> flag <a href="https://nodejs.org/api/esm.html" rel="nofollow noreferrer">node.js : HTTPS and HTTP imports</a></p>
<pre class="lang-javascript prettyprint-override"><code>// test.node.mjs

import JSZip from 'https://cdn.jsdelivr.net/npm/jszip/+esm';
console.log(JSZip);
</code></pre>
<p>and then run with</p>
<pre class="lang-none prettyprint-override"><code>node --experimental-network-imports --no-warnings .\test.node.mjs
</code></pre>

Q: How can I get Javascript to run through a list of predefined responses, in order? A: <p>You said:</p>
<blockquote>
<p>Currently the bot responds with the last item from the list every time. I think the problems I need to solve are basically:</p>
<ol>
<li><p>getting the function to run through the list consecutively, keeping track of which item was used last</p>
</li>
<li><p>running the function to generate a new word every time the user clicks submit, without having to reload the page (this is a problem I've also had in the past creating random word generators)</p>
</li>
</ol>
</blockquote>
<p>Since you didn't show any code related to #2 (and since it's really a completely separate problem that should be in its own separate question), I'm going to ignore it and focus on #1.</p>
<hr />
<p>In the function <code>sendMessage</code>, you use a timer to create the &quot;bot response&quot;:</p>
<pre class="lang-js prettyprint-override"><code>  setTimeout(() =&gt; {
    appendMessage(&quot;bot&quot;, botMessage);
  }, 1000);
</code></pre>
<p>The <code>botMessage</code> is a reference to a variable in the outer scope. It is created by looping over the array <code>words</code>:</p>
<pre class="lang-js prettyprint-override"><code>var words = [
  &quot;apple&quot;,
  &quot;banana&quot;,
  &quot;cherry&quot;,
  &quot;date&quot;,
  &quot;elderberry&quot;,
  &quot;fig&quot;,
  &quot;grape&quot;,
  &quot;honeydew&quot;,
];

for (var index = 0, len = words.length; index &lt; len; ++index) {
  var botMessage = words[index];
  console.log(botMessage);
}
</code></pre>
<p>Each time that the loop iterates, the value of <code>botMessage</code> is updated (overwritten), so when the loop runs for the last time, the value of <code>botMessage</code> is equal to the last element in the array (<code>&quot;honeydew&quot;</code>). So, every time the &quot;bot response&quot; is created, the value is always <code>&quot;honeydew&quot;</code>.</p>
<p>This aligns with your observation:</p>
<blockquote>
<p>Currently the bot responds with the last item from the list every time.</p>
</blockquote>
<p>In order to fix this, you need to keep track of the &quot;current position&quot; in the list so that each time you need to create a bot message, you can use the corresponding word from the array instead of always referring to a static variable.</p>
<p>Because arrays are indexed by integers, you can just keep track of the index and increment it each time — and when you reach the last index in the array, set it back to <code>0</code> to cycle. You might write it this way using the <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Operators/Remainder" rel="nofollow noreferrer">remainder operator (<code>%</code>)</a>:</p>
<pre class="lang-js prettyprint-override"><code>const words = [
  &quot;apple&quot;,
  &quot;banana&quot;,
  &quot;cherry&quot;,
  &quot;date&quot;,
  &quot;elderberry&quot;,
  &quot;fig&quot;,
  &quot;grape&quot;,
  &quot;honeydew&quot;,
];

let wordIndex = 0;

function getNextWord() {
  const word = words[wordIndex];
  wordIndex = (wordIndex + 1) % words.length;
  return word;
}
</code></pre>
<p>Then, back in the function <code>sendMessage</code>, you can initialize <code>botMessage</code> just before the <code>setTimeout</code> like this:</p>
<pre class="lang-js prettyprint-override"><code>  const botMessage = getNextWord();
  setTimeout(() =&gt; appendMessage(&quot;bot&quot;, botMessage), 1000);
</code></pre>
<hr />
<p>If this is a scenario you encounter repeatedly, you could create an abstraction to cycle over an array, keeping track of the index state in a <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Classes" rel="nofollow noreferrer">class</a> that implements the <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Iteration_protocols" rel="nofollow noreferrer">iteration protocols</a> — for example:</p>
<pre class="lang-js prettyprint-override"><code>class CyclingIterator {
  #index;

  constructor(array) {
    this.array = [...array];
    this.#index = 0;
  }

  [Symbol.iterator]() {
    return this;
  }

  next() {
    const value = this.array[this.#index];
    this.#index = (this.#index + 1) % this.array.length;
    return { value };
  }
}

const cycleWords = new CyclingIterator([
  &quot;apple&quot;,
  &quot;banana&quot;,
  &quot;cherry&quot;,
  &quot;date&quot;,
  &quot;elderberry&quot;,
  &quot;fig&quot;,
  &quot;grape&quot;,
  &quot;honeydew&quot;,
]);
</code></pre>
<p>…and in the function <code>sendMessage</code> you can create <code>botMessage</code> by accessing the next value from the iterator:</p>
<pre class="lang-js prettyprint-override"><code>  const botMessage = cycleWords.next().value;
  setTimeout(() =&gt; appendMessage(&quot;bot&quot;, botMessage), 1000);
</code></pre>
<hr />
<p>Here's a code snippet with the code in your question and the modifications described above:</p>
<p><div class="snippet" data-lang="js" data-hide="true" data-console="false" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code snippet-currently-hidden">
<pre class="snippet-code-js lang-js prettyprint-override"><code>document.getElementById('send-button').addEventListener('click', sendMessage);
document.getElementById('message-input').addEventListener('keypress', function (e) {
  if (e.key === 'Enter') {
    sendMessage();
  }
});


class CyclingIterator {
    #index;

    constructor(array) {
        this.array = [...array];
        this.#index = 0;
    }

    [Symbol.iterator]() {
        return this;
    }

    next() {
        const value = this.array[this.#index];
        this.#index = (this.#index + 1) % this.array.length;
        return { value };
    }
}

const cycleWords = new CyclingIterator([
    "apple",
    "banana",
    "cherry",
    "date",
    "elderberry",
    "fig",
    "grape",
    "honeydew",
]);

function sendMessage() {
    var input = document.getElementById("message-input");
    var message = input.value.trim();

    if (message === "") return;

    appendMessage("user", message);
    input.value = "";

    const botMessage = cycleWords.next().value;
    setTimeout(() =&gt; appendMessage("bot", botMessage), 1000);
}


function appendMessage(sender, message) {
  var chatWindow     = document.getElementById('chat-window');
  var messageElement = document.createElement('div');
  messageElement.classList.add('message', sender);
  messageElement.textContent = message;
  chatWindow.appendChild(messageElement);
  chatWindow.scrollTop = chatWindow.scrollHeight;
}</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;div class="chatbox"&gt;
  &lt;div class="chat-window" id="chat-window"&gt;

    &lt;!-- Messages displayed here --&gt;

  &lt;/div&gt;
  &lt;div class="chat-input"&gt;
    &lt;input type="text" id="message-input" placeholder="Type a message..."&gt;
    &lt;button id="send-button"&gt;Send&lt;/button&gt;
  &lt;/div&gt;
&lt;/div&gt;</code></pre>
</div>
</div>
</p>
